-- =============================================================================
-- V37 视频墙导航数据源（达梦方言）—— 大屏「前端数据全后端化」P0-①
--   目的：把前端 screen/components/video-wall/videoWallStore.ts 内代码生成的
--         targetTree/videoTree/cameraTargetMap/defaultHighAltitudeCameras 迁到后端，
--         由新增 GET /api/v1/video/wall-navigation 提供。
--   建模：单表 fac_video_wall_node 承载四类节点（node_kind 区分）：
--         CATEGORY(6) / AREA(5) / HIGH_AR(4) 为真实行；TARGET(120) 为业务对象行，
--         行上携带 parent_code(所属分类) + area_code(所属厂区) + cam_count(通道数)。
--   派生：摄像头通道（v-{i}-{j}，j=1..cam_count）与其→目标映射由服务端按 TARGET 行
--         确定性派生（占位通道命名，接真实 MDM 设备后改读设备表），不单独建表。
--   口径：节点编码/名称与前端原生成逻辑逐位对齐（本文件由脚本生成，勿手改数值）。
--   与 h2/V37 同内容；达梦逐条 INSERT（不使用多行 VALUES）。
-- =============================================================================

CREATE TABLE fac_video_wall_node (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    node_code VARCHAR2(32) NOT NULL,
    node_kind VARCHAR2(16) NOT NULL,
    label VARCHAR2(64) NOT NULL,
    parent_code VARCHAR2(32),
    area_code VARCHAR2(32),
    cam_count NUMBER(9) DEFAULT 0 NOT NULL,
    sort_no NUMBER(9) DEFAULT 0 NOT NULL
);

